svg.script:


	/*  Crossmatch Guardian User Guidance Color Scheme
		#D1D2D4 - Light gray background
		#525E66 - Dark gray of prism boarder
		#0479BF - Prism light blue fill
		#0F5E8F - Prism dark blue outline
		#ECECED - Initial animated hand outline
		#FFFFFF opacity="0.5"  - Initial animated hand fill

		#FFBF40 - Yellow pressure corona, finger status and message bar
		#5CE224	- Prism capture complete green, finger status and message bar
		#E63622 - finger status and message bar

		"FPx":0 - Color #264A80 - Medium blue
		"FPx":1 - Color #3C7CF4 - light blue
		"FPx":2 - Color #FFBF40 - Yellow
		"FPx":3 - Color #e63622 - Red
		"FPx":4 - Color #3C7CF4 - light blue
		"FPx":5 - Color #5CE224 - Green
	*/


	/********************************************************************************
	getPrismaBBox will get the primsma object that will contain rolled preview images.
	********************************************************************************/
	function getPrismaBBox() {

		// Get object for the area that rolled images will be displayed.
		var prisma = document.getElementById('PrismaPath');
		try {
			var cb = getScreenBBox_impl(prisma);
			return([parseInt(cb.x.toFixed(0)), parseInt(cb.y.toFixed(0)), parseInt(cb.width.toFixed(0)), parseInt(cb.height.toFixed(0))]);
		  }
		catch(ex) {
			alert(ex);
		}
		return(0);
	}


	/********************************************************************************
	getPrismaCoordinates will get the Coordinates of the primsma object that
	contains rolled preview images.
	returns coordArr[] with the 4 prism box used to display rolled images.
	********************************************************************************/
	function getPrismaCoordinates() {
		var prismaBox = getPrismaBBox();
		var coordArr = new Array();
		coordArr[0] = [prismaBox[0],prismaBox[1]];
		coordArr[1] = [prismaBox[0]+prismaBox[2],prismaBox[1]];
		coordArr[2] = [prismaBox[0]+prismaBox[2],prismaBox[1]+prismaBox[3]];
		coordArr[3] = [prismaBox[0],prismaBox[1]+prismaBox[3]];
		return (coordArr);
	}


	/********************************************************************************
	//begin loading page.
	********************************************************************************/
	function onLoad() {
		window.parent.parseUrlArguments();
		Update();

		window.parent.svgUpdate = function() {Update();}
		window.parent.getPrismaBBox = function() {return getPrismaBBox();}
		window.parent.getPrismaCoordinates = function() {return getPrismaCoordinates();}
	}


	/* Update will get roll image
	*/
	function Update() {
		try {

			// Get URI argument from html			
			var args = window.parent.getArguments();

			//change the default graphic, if the args is correct
			if (args == null)
				return;			// Return - nothing to do


			/* Check each Parameter and display data */

			// Diplay Result icon. Limit to the icon # 0 to 8 and 11 in graphic array.
			if (args.Result >= 0 && args.Result <= 11) {	
				SetResult(args.Result);
			}

			// Display Results text
			if (args.resultText && args.resultText.length > 0) {
				SetMessage(args.resultText,args.Result);
			}
			else {
				args.resultText = '';
				SetMessage('',0);		// Clear text
			}

			// Change hand icon color prompt
			SetHP(args.HP2,2);		// set Left Hand color
			SetHP(args.HP1,1);		// Set right hand color

			// Change finger icon color prompt
			SetFP(args.FP1,1);		// Set right thumb color
			SetFP(args.FP2,2);		// Set right index finger color
			SetFP(args.FP3,3);		// Set right middle finger color
			SetFP(args.FP4,4);		// Set right ring finger color
			SetFP(args.FP5,5);		// Set right little finger color

			SetFP(args.FP6,6);		// Set left thumb color
			SetFP(args.FP7,7);		// Set left index finger color
			SetFP(args.FP8,8);		// Set left middle finger color
			SetFP(args.FP9,9);		// Set left ring finger color
			SetFP(args.FP10,10);	// Set left little finger color


			// Enable buttons
			SetButton(args.ButtonRetry, "Retry");
			SetButton(args.ButtonConfirm, "Confirm");

			// Analyse Peripherality
			if(args.peripherality && args.peripherality.length > 0) {
				SetPeripherality(args.peripherality);
				return;
			}

		}
		catch(ex) {
			alert(ex);
		}
	}


	/********************************************************************************
		Called by Update
		SetResult will show or hide the Result Icons by Result-Parameter
	Input:
	  result icon number
		0 - Prompt to start horizontal roll displayed at start of roll capture
		1 - green Icon (OK) displayed when roll capture is complete
		2 - General error
		3 - Clean Platen
		4 - Recording error
		5 - Roll error
		6 - Segmentation error displayed if flat captured images can not be segmented
		7 - Quality-Check error
		8 - Sequence-Check error displayed when roll does not match flat capture
		11 - Prompt to start vertical roll displayed at start of roll capture
	********************************************************************************/
	function SetResult(result) {
	  	var i;
		// loop to hide all of the Result Icons and show only the correct one
		for (i = 0; i <= 11; i++) {
			// All the Result icon images are in the format IDIconResult_X where X is the Argument number 
			var resultIcon = document.getElementById('IDIconResult_' + i);
			if (resultIcon) {
				if (i == result)
					resultIcon.setAttribute("display","inline");	// Display icon
				else
					resultIcon.setAttribute("display","none");		// hide icon
			}
		}
	}


	/********************************************************************************
		Called by Update
		SetMessage will display text string and change background color
	Inputs:
		messageText is string displayed to the left of the rusults icon
		color will determine the color of text and background
				0 - Yellow text on dark gray background
				1 - Dark blue text on green background
				else - White text on red background
	********************************************************************************/
	function SetMessage(messageText, color) {
  		var messageBar = document.getElementById('MessageBar');
		var messageTxt = document.getElementById('MessageText');
		var txt = messageTxt.firstChild;

		if (messageBar && messageTxt) {
			switch(color) {
				case 0:	//no Error
					messageBar.setAttribute("fill","#525E66");	//Dark gray of prism boarder
					messageTxt.setAttribute("fill","#FFBF40");	//yellow
					break;

				case 1: //OK when result == 1
					messageBar.setAttribute("fill","#5CE224");	//green
					messageTxt.setAttribute("fill","#072B61");	//dark blue
					break;

				default: //Error used for results > 1
					messageBar.setAttribute("fill","#E63622");	//red
					messageTxt.setAttribute("fill","#ffffff");	//white
					break;
			}

			txt.nodeValue = messageText;
			messageTxt.setAttribute("display","inline");
		}
	}


	/********************************************************************************
	  called by Update
	  SetHP will change the color of the hand based on the capture state

	INPUT: ColorState  0 - inactive set color to #264A80 (medium blue)  *Default
	                   1 - active set color to #ffffff (white)
				       else - inactive 
	       hand 2 - left hand
	            1 - right hand
	********************************************************************************/
	function SetHP(ColorState, hand) {
		if(hand < 1 || hand > 2)
			return;	// not a valid hand

		var handIcon = document.getElementById('IDHandPath_' + hand);
		switch(ColorState) {			
			case 1:
				//active
				handIcon.setAttribute("fill","#ffffff");	// White
				break;

			case 0:
			default:
				//inactive
				handIcon.setAttribute("fill","#264A80");	// Medium blue
				break;
		}
	}


	/********************************************************************************
	  called by Update
	  SetFP will change the color of the active finger icon
	  Update will call SetFP once for each finger. 

	INPUT: ColorState  0 - Color #264A80 - Medium Blue  - Finger is not active and not captured
	                   1 - Color #5CE224 - Green for 1 second and then #3C7CF4 light blue - fingerprint successfully captured
	                   2 - Color #FFBF40 - Yellow - Fingerprint is actively being captured
	                   3 - Color #e63622 - Red - Fingerprint has roll error
	                   4 - Color #3C7CF4 - light blue - fingerprint successfully captured
	                   5 - Color #5CE224 - Green - Fingerprint successfully caputured

	      finger index into figner number 1 is right thumb to 10 is left little finger
			     index, X must match the IDStateFinger_X graphic array
	********************************************************************************/
	function SetFP(ColorState, finger) {
		if(finger < 1 || finger > 10)
			return;	// not a valid finger

		var fingerPositionIcon = document.getElementById('IDStateFinger_' + finger);
		var fingerColor =  fingerPositionIcon.getAttribute("fill");

		switch(ColorState) {
			case 0:
				//not yet scanned
				fingerPositionIcon.setAttribute("fill","#264A80");
				break;

			case 1:
				// already scanned
				// TODO: Fine out why this timeout code does not work with layoutserver
				fingerPositionIcon.setAttribute("fill","#5CE224");
					setTimeout( function() {
						fingerPositionIcon.setAttribute("fill","#3C7CF4");
					},1000);

				break;

			case 2:
				//actual
				fingerPositionIcon.setAttribute("fill","#FFBF40");
				break;

			case 3:
				//Roll error
				fingerPositionIcon.setAttribute("fill","#e63622");
				break;

			case 4:
				// already scanned
				fingerPositionIcon.setAttribute("fill","#3C7CF4");
				break;

			case 5:
				// already scanned
				fingerPositionIcon.setAttribute("fill","#5CE224");
				break;

			default:
				fingerPositionIcon.setAttribute("fill","#264A80");
				break;
		}
	}


	/********************************************************************************
	  called by Update
	  SetButton will change the button icon to the active or inactive state
	  The button names are:
		IDButtonRetryActive
		IDButtonRetryInactive
		IDButtonConfirmActive
		IDButtonConfirmInactive
	INPUTS:
		state 	0 - inactive button is grayed out
				1 - active button is raised
				2 - button is hidden
		button  - string containing the name of the button. Used to get graphics element
				 must be set to "Retry" or "Confirm".
	********************************************************************************/
	function SetButton(state, button) {
  		var ActiveButtonIcon = document.getElementById('IDButton' + button + 'Active');
  		var InactiveButtonIcon = document.getElementById('IDButton' + button + 'Inactive');

		switch(state) {
			case 0:
				//inactive
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","inline");
				if (button == "Confirm") {
					MoveRetryButton(0);
				}
				break;

			case 1:
				//active
				ActiveButtonIcon.setAttribute("display","inline");
				InactiveButtonIcon.setAttribute("display","none");
				if (button == "Confirm") {
					MoveRetryButton(0);
				}
				break;

			case 2:
				//hidden
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","none");
				//if the Button "Confirm" is unvisible, move the Retry-Button to right
				if (button == "Confirm") {
					MoveRetryButton(1);
				}
				break;

			default:
				//inactive
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","inline");
				break;
		}
	}


	/********************************************************************************
	  called by SetButton
	  MoveRetryButton will preposition Retry button if Confirm button is hidden

	INPUTL
		position - Retry button position
		           0 - initial possition as defined by SVG graphics
				   1 - move button to left
	********************************************************************************/
	function MoveRetryButton(position) {
		var retryBtn1 = document.getElementById('IDButtonRetryActive');
		var retryBtn2 = document.getElementById('IDButtonRetryInactive');

		if (position == 1) {
			retryBtn1.setAttribute("transform","translate(113,0)");
			retryBtn2.setAttribute("transform","translate(113,0)");
		} 
		else {
			retryBtn1.setAttribute("transform","translate(0,0)");	// original position
			retryBtn2.setAttribute("transform","translate(0,0)");
		}
	}


	/********************************************************************************
	 called by Update
	 SetPeripherality is called when one of the perifpherality arguments is set to true
	  This function will display the peripherality icon
	INPUT: peripherality[] - contains up to three entries
	                       = left - 	OBJECT_POSITION_TOO_LEFT
	                       = right - 	OBJECT_POSITION_TOO_RIGHT
	                       = top - 		OBJECT_POSITION_TOO_HIGH
	                       = bottom -	OBJECT_POSITION_TOO_LOW
	 calculate position = 1 if too far left
	                    = 2 if too far right
	                    = 3 if too far left and too right
	                    = 4 if too high
	                    = 5 if too far left and too high
	                    = 6 if too far right and too high
	                    = 7 if too far left, too far right and too high
						= 8 too far to too low
						= 9 if too far left and too low
						=10 if too far right and too low
						=11 if too far left, too far right and too low
	********************************************************************************/
	function SetPeripherality(peripherality) {
		var position = 0;
		if(peripherality.indexOf("left") != -1) position+= 1;
		if(peripherality.indexOf("right") != -1) position+= 2;
		if(peripherality.indexOf("top") != -1) position+= 4;
		if(peripherality.indexOf("bottom") != -1) position+= 8;

		switch(position) {
			case 1: //too far left
			case 2: //too far right
			case 4: //too high
			case 5: //too far left and too high
			case 6:	//too far right and too high
			case 8:	//too low
			case 9:	//too far left and too low
			case 10: //too far right and too low
				ShowPeripheralityIcon(position);
				break;

			case 3:	// too far left and too far right
				ShowPeripheralityIcon(1);	// display too far left
				break;

			case 7:	// too far left and too far right and too high
				ShowPeripheralityIcon(5);	// display too far left and too high
				break;

			case 11:// too far left and too far right and too low
				ShowPeripheralityIcon(9);	// display too far left and too low
				break;

			default:
				break;
		}

	}

	/********************************************************************************
	 called by SetPeripherality
	 ShowPeripheralityIcon will display the IDIconPeripherality_X icon
	INPUT: position = 1 to 10 to match svg array of graphics in IDIconPeripherality_ 
	********************************************************************************/
	function ShowPeripheralityIcon(peripherality) {
	  	var i;

		// Display only one icon
		for (i = 0; i <= 10; i++) {
			var peripheralityIcon = document.getElementById('IDIconPeripherality_' + i);
			if (peripheralityIcon) {
				if (i == peripherality)
					peripheralityIcon.setAttribute("display","inline");	// Display
				else
					peripheralityIcon.setAttribute("display","none");	// Hide
			}
		}
	}
